// Deterministic normalization only. No LLM, no external calls.
function pad(n){return String(n).padStart(2,'0');}
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const now=moscowIsoNow();
const stamp=moscowStamp();
const req=$('Set Manual Intake Request').first().json;
const reqId=req.agent_request_id;
const reqQuery=req.query||'';
function str(v){return v==null?'':String(v).trim();}
function low(v){return str(v).toLowerCase();}
function any(b,arr){for(const w of arr){if(b.indexOf(w)>=0)return true;}return false;}
function normUrl(u){u=str(u);if(!u)return '';try{const x=new URL(u.split('#')[0]);x.hostname=(x.hostname||'').toLowerCase();let p=x.pathname||'/';if(p.length>1&&p.endsWith('/'))p=p.slice(0,-1);x.pathname=p;return x.toString();}catch(e){return u.toLowerCase();}}
function hashText(s){s=str(s);let h=5381;for(let i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))>>>0;}return ('00000000'+h.toString(16)).slice(-8);}
const recs=$('Set Manual Records').all().map(i=>i.json);
const out=[];let idx=0;
for(const r of recs){
  idx++;
  const platform=low(r.platform);
  const source_type=low(r.source_type);
  const source_url=normUrl(r.source_url);
  const post_url=normUrl(r.post_url);
  const profile_url=normUrl(r.profile_url);
  const text_context=str(r.text_context);
  const comment_text=str(r.comment_text);
  const rth=low(r.record_type_hint)||'unknown';
  const tpt=low(r.touchpoint_type)||'';
  const blob=(text_context+' '+comment_text+' '+str(r.interest_topic)+' '+str(r.probable_need)).toLowerCase();
  const text_hash=hashText(text_context+'||'+comment_text);
  let dedup_key;
  if(post_url){dedup_key=platform+'::post::'+post_url;}
  else if(source_url){dedup_key=platform+'::source::'+source_url;}
  else if(profile_url&&text_hash){dedup_key=platform+'::profile_text::'+profile_url+'::'+text_hash;}
  else{dedup_key=platform+'::text::'+text_hash;}
  let region_hint='';
  if(any(blob,['москва','мск','moscow','подмосковье']))region_hint='Москва/МО';
  let urgency_hint='low';
  if(any(blob,['срочно','сегодня','отказал','просрочк','нужны деньги']))urgency_hint='high';
  else if(any(blob,['интересуется','ищет','вопрос','куда обратиться']))urgency_hint='medium';
  let lead_intent_hint;
  if(rth==='competitor_activity'||rth==='irrelevant'||tpt==='source_candidate'||tpt==='irrelevant_source'||tpt==='weak_market_noise')lead_intent_hint='low';
  else if(rth==='question_objection'||tpt==='forum_discussion'||tpt==='review_source'||rth==='market_signal')lead_intent_hint='medium';
  else lead_intent_hint='low';
  if(urgency_hint==='high'&&any(blob,['нужен кредит','нужны деньги','отказал','просрочк'])&&rth!=='competitor_activity'&&rth!=='irrelevant')lead_intent_hint='high';
  let confidence_score=1;
  if(rth==='competitor_activity'&&source_url)confidence_score=80;
  else if(rth==='question_objection'||rth==='market_signal')confidence_score=70;
  if(tpt==='source_candidate')confidence_score=40;
  if(rth==='irrelevant')confidence_score=1;
  let lead_temperature='none';
  if(rth==='competitor_activity'||rth==='irrelevant')lead_temperature='none';
  else if(tpt==='source_candidate')lead_temperature='cold';
  else if(rth==='question_objection'||tpt==='forum_discussion'||(tpt==='review_source'&&str(r.probable_need)))lead_temperature='warm';
  else if(rth==='market_signal')lead_temperature='warm';
  if(lead_intent_hint==='high'&&urgency_hint==='high')lead_temperature='hot';
  let next_action='investigate';
  if(rth==='irrelevant')next_action='ignore';
  else if(rth==='competitor_activity')next_action='monitor';
  else if(rth==='client_pain')next_action='create_content';
  else if(rth==='question_objection')next_action='investigate';
  else if(rth==='market_signal')next_action='investigate';
  const estimated_analysis_cost_usd=(rth==='irrelevant')?0:0.02;
  out.push({ json: {
    record_id:'rec_'+stamp+'_'+idx,
    agent_request_id:reqId,
    created_at:now,
    source_type:source_type,
    platform:platform,
    source_url:source_url,
    post_url:post_url,
    profile_url:profile_url,
    profile_name:str(r.profile_name),
    author_handle:str(r.author_handle),
    published_at:'',
    region_hint:region_hint,
    service_hint:low(r.service_hint),
    query:reqQuery,
    text_context:text_context,
    comment_text:comment_text,
    contact_public:'',
    contact_channel:'none',
    dedup_key:dedup_key,
    record_type_hint:rth,
    touchpoint_type:tpt,
    lead_intent_hint:lead_intent_hint,
    urgency_hint:urgency_hint,
    interest_topic:str(r.interest_topic),
    probable_need:str(r.probable_need),
    competitor_related:(r.competitor_related===true||low(r.competitor_related)==='true'),
    competitor_name:str(r.competitor_name),
    semantic_keywords:'',
    ad_channel_hint:'',
    confidence_score:confidence_score,
    lead_temperature:lead_temperature,
    next_action:next_action,
    responsible:'',
    dedup_status:'pending',
    approval_status:'new',
    approved_by:'',
    approved_at:'',
    estimated_analysis_cost_usd:estimated_analysis_cost_usd,
    manager_note:'',
    notes:'stage_3_1_manual_intake'
  }});
}
return out;

// Dedup against market_record_registry (by dedup_key) and within this batch. No external calls.
function str(v){return v==null?'':String(v).trim();}
const recs=$('Normalize Manual Records').all().map(i=>i.json);
const __req=$('Set Manual Intake Request').first().json||{};
let reg=[];
try{reg=$('Read market_record_registry').all().map(i=>i.json).filter(Boolean);}catch(e){reg=[];}
const regSet=new Set(reg.map(r=>str(r&&r.dedup_key)).filter(Boolean));
const seen=new Set();
const out=[];
for(const r of recs){
  const key=str(r.dedup_key);
  let dedup_status='unique';
  let approval_status=r.approval_status||'new';
  if(key&&regSet.has(key)){dedup_status='duplicate_in_registry';approval_status='duplicate';}
  else if(key&&seen.has(key)){dedup_status='duplicate_in_batch';approval_status='duplicate';}
  else{dedup_status='unique';if(key)seen.add(key);}
  const __irr=(str(r.record_type_hint)==='irrelevant');
  out.push({ json: Object.assign({}, r, { dedup_status:dedup_status, approval_status:approval_status,
    source_run_id:str(__req.agent_request_id), data_mode:'manual_test',
    quality_status:(__irr?'quarantined':'healthy'), report_eligible:(!__irr), review_status:'confirmed', quality_flags:'' }) });
}
return out;

// Build market_record_registry rows for UNIQUE records only (15 columns). No external calls.
function str(v){return v==null?'':String(v).trim();}
function hashText(s){s=str(s);let h=5381;for(let i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))>>>0;}return ('00000000'+h.toString(16)).slice(-8);}
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
const now=moscowIsoNow();
const recs=$('Dedup Against Registry').all().map(i=>i.json);
const out=[];
for(const r of recs){
  if(str(r.dedup_status)!=='unique')continue;
  const text_hash=hashText(str(r.text_context)+'||'+str(r.comment_text));
  out.push({ json: {
    dedup_key:str(r.dedup_key),
    source_type:str(r.source_type),
    platform:str(r.platform),
    source_url:str(r.source_url),
    post_url:str(r.post_url),
    profile_url:str(r.profile_url),
    author_handle:str(r.author_handle),
    text_hash:text_hash,
    first_seen_at:now,
    last_seen_at:now,
    last_route:'raw_market_records',
    last_processing_status:'intake_recorded',
    last_entity_type:str(r.record_type_hint),
    agent_request_id:str(r.agent_request_id),
    note:'manual_intake_stage_3_1'
  }});
}
return out;

// One agent_requests row (21 columns). status=needs_review. No external calls.
function str(v){return v==null?'':String(v).trim();}
const req=$('Set Manual Intake Request').first().json;
const recs=$('Dedup Against Registry').all().map(i=>i.json);
const total=recs.length;
const unique=recs.filter(r=>str(r.dedup_status)==='unique').length;
const duplicate=recs.filter(r=>str(r.dedup_status).indexOf('duplicate')===0).length;
const irrelevant=recs.filter(r=>str(r.record_type_hint)==='irrelevant').length;
let cost=0;for(const r of recs){cost+=Number(r.estimated_analysis_cost_usd)||0;}
cost=Math.round(cost*1000)/1000;
return [{ json: {
