// Final run summary. No external calls.
function str(v){return v==null?'':String(v).trim();}
const req=$('Set Manual Intake Request').first().json;
const recs=$('Dedup Against Registry').all().map(i=>i.json);
const total=recs.length;
const unique=recs.filter(r=>str(r.dedup_status)==='unique').length;
const duplicate=recs.filter(r=>str(r.dedup_status).indexOf('duplicate')===0).length;
const irrelevant=recs.filter(r=>str(r.record_type_hint)==='irrelevant').length;
// Audit rows = every intake record stored (incl. irrelevant). Irrelevant rows are STORED audit rows,
// NOT hard-skipped (S3-D19). Eligible-for-analysis = unique AND relevant. Estimated future Claude cost
// (WF08) is derived ONLY from eligible-unique rows; THIS workflow performs no analysis (actual cost=0).
const EST_ANALYSIS_COST_PER_RECORD_USD=0.004; // claude-sonnet-4-6 rough per-record estimate (documented)
const eligible_unique_for_analysis=recs.filter(r=>str(r.dedup_status)==='unique'&&str(r.record_type_hint)!=='irrelevant').length;
const estimated_future_analysis_cost_usd=Math.round(eligible_unique_for_analysis*EST_ANALYSIS_COST_PER_RECORD_USD*10000)/10000;
const platform_counts={};const record_type_counts={};
for(const r of recs){
  const p=str(r.platform)||'unknown';platform_counts[p]=(platform_counts[p]||0)+1;
  const t=str(r.record_type_hint)||'unknown';record_type_counts[t]=(record_type_counts[t]||0)+1;
}
return [{ json: {
  workflow:'07 - Manual Touchpoint Intake',
  agent_request_id:req.agent_request_id,
  total_records:total,
  unique_count:unique,
  duplicate_count:duplicate,
  irrelevant_count:irrelevant,
  platform_counts:platform_counts,
  record_type_counts:record_type_counts,
  data_mode:'manual_test',
  audit_rows_written:total,
  raw_market_records_written:total,
  eligible_unique_for_analysis:eligible_unique_for_analysis,
  irrelevant_items:irrelevant,
  hard_skipped_items:0,
  actual_analysis_cost_usd:0,
  estimated_future_analysis_cost_usd:estimated_future_analysis_cost_usd,
  cost_status:'not_applicable',
  external_calls:0,
  llm_calls:0,
  registry_rows_written:unique,
  next_action:'Review raw_market_records and market_record_registry; then design/build the Touchpoint Analyzer (Stage 3.2). No scraping, no LLM here.'
}}];

